scwin.trigger1_onclick = function(e) {
    gridView1.setRowStatusColumnWidth(0);
};
scwin.checkWidth = function() {
    var width = WebSquare.wUnit.getJq("#gridView1_body_tbody").width() + WebSquare.wUnit.getJq("#gridView1_scrollY_div").outerWidth();
    var win = window.innerWidth || document.documentElement.clientWidth || document.body.clientWidth;;
    if (width / win > 0.99) {
        return true;
    }
    return false;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Propery 탭 또는 Source 탭에서 gridView1 의 autoFit 부분을 확인한다.
    //1. Check the autoFit portion of gridView1 in the Propery or Source tabs.
    //Verify 1. autoFit="allColumn"
    //Test step 2. rowNumVisible 부분을 확인한다.
    //Check rowNumVisible.
    //Verify 2. rowNumVisible="true"
    //Test step 3. rowNumWidth 부분을 확인한다.
    //Check rowNumWidth.
    //Verify 3. rowNumWidth="50"
    //Test step 4. rowStatusHeaderValue 부분을 확인한다.
    //Check the rowStatusHeaderValue part.
    //Verify 4. rowStatusHeaderValue="상태" 
    //Test step 5. keepDefaultColumnWidth 부분을 확인한다.
    //. Check the keepDefaultColumnWidth part.
    //Verify 5. keepDefaultColumnWidth="true"
    //Test step 6. Script 탭 또는 Source 탭에서 scwin.trigger1_onclick 부분을 확인한다.
    //In the Script tab or the Source tab, check the scwin.trigger1_onclick section.
    //gridView1.setRowStatusColumnWidth(0);
    //Test step 7. 브라우저에서 상태 컬럼 width 0 버튼을 클릭한다.
    //In the browser, click the Status column width 0 button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 7. autofit allcolumn 에 맞게 사이즈가 조절된다. (그전버전에서는 gridView 우측 영역에 여백이 생겼음)
    //It is resized to autofit allcolumn. (In previous versions there was a margin in the right area of gridView)
    WebSquare.wUnit.addCommand("assert", "scwin.checkWidth()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 29-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
